export enum Operation {
  Add = '+',
  Subtract = '-',
  Multiply = '×',
  Divide = '÷'
}

export interface MathProblem {
  num1: number;
  num2: number;
  operation: Operation;
  answer: number;
}

export enum GameState {
  Playing,
  Correct,
  Incorrect
}

import { GoogleGenAI } from "@google/genai";

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const getRoyalComment = async (isCorrect: boolean, number: number): Promise<string> => {
  if (!apiKey) return ""; // Fail silently if no key

  try {
    const prompt = isCorrect 
      ? `Give a very short, one-sentence fun fact or encouraging compliment in Georgian for a kid named Thoma who just calculated the number ${number} correctly. Pretend you are a wise Royal Advisor.`
      : `Give a very short, one-sentence encouraging message in Georgian for a kid named Thoma who got a math problem wrong. Tell him to try again like a brave king.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "";
  } catch (error) {
    console.error("Gemini error:", error);
    return "";
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger';
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  className = '', 
  ...props 
}) => {
  const baseStyle = "px-6 py-3 rounded-xl font-bold text-lg transition-transform active:scale-95 shadow-lg";

  const variants = {
    primary: "bg-blue-600 hover:bg-blue-500 text-white shadow-blue-500/30",
    secondary: "bg-purple-600 hover:bg-purple-500 text-white shadow-purple-500/30",
    danger: "bg-red-500 hover:bg-red-400 text-white shadow-red-500/30"
  };

  return (
    <button 
      className={`${baseStyle} ${variants[variant]} ${className}`} 
      {...props}
    >
      {children}
    </button>
  );
};

import React, { useEffect, useState } from 'react';
import { GameState } from '../types';
import { Button } from './Button';
import { getRoyalComment } from '../services/geminiService';

interface ResultOverlayProps {
  gameState: GameState;
  onReset: () => void;
  correctAnswer: number;
}

export const ResultOverlay: React.FC<ResultOverlayProps> = ({ gameState, onReset, correctAnswer }) => {
  const [comment, setComment] = useState<string>('');

  const isCorrect = gameState === GameState.Correct;
  // Use the filenames exactly as requested. 
  // Ensure king.png and king1.png are in the public root folder.
  const imageSrc = isCorrect ? 'king.png' : 'king1.png'; 
  const title = isCorrect ? 'ყოჩაღ თომა!' : 'კიდევ სცადე!';
  const bgColor = isCorrect ? 'bg-green-500/90' : 'bg-red-500/90';

  useEffect(() => {
    let mounted = true;
    const fetchComment = async () => {
      const text = await getRoyalComment(isCorrect, correctAnswer);
      if (mounted && text) {
        setComment(text);
      }
    };
    fetchComment();
    return () => { mounted = false; };
  }, [gameState, isCorrect, correctAnswer]);

  if (gameState === GameState.Playing) return null;

  return (
    <div className={`fixed inset-0 z-50 flex items-center justify-center p-4 backdrop-blur-sm ${bgColor} transition-colors duration-500`}>
      <div className="bg-white rounded-3xl p-8 max-w-md w-full shadow-2xl text-center transform animate-bounce-short">
        <h2 className={`text-4xl font-black mb-6 ${isCorrect ? 'text-green-600' : 'text-red-600'}`}>
          {title}
        </h2>

        <div className="relative w-64 h-64 mx-auto mb-6 rounded-2xl overflow-hidden border-4 border-yellow-400 shadow-xl bg-gray-100">
           {/* Fallback to placeholders if local images aren't found, but defaults to requested filenames */}
          <img 
            src={imageSrc} 
            alt="King Status" 
            className="w-full h-full object-cover"
            onError={(e) => {
              // Fallback just in case the files are missing so the app doesn't look broken
              const target = e.target as HTMLImageElement;
              target.src = isCorrect 
                ? "https://picsum.photos/400/400?random=1" 
                : "https://picsum.photos/400/400?random=2";
            }}
          />
        </div>

        {comment && (
          <p className="text-gray-700 italic mb-6 text-lg border-l-4 border-yellow-400 pl-4 text-left">
            "{comment}"
          </p>
        )}

        <div className="text-2xl font-bold text-gray-800 mb-8">
          {!isCorrect && <span>სწორი პასუხი იყო: {correctAnswer}</span>}
        </div>

        <Button onClick={onReset} className="w-full text-xl py-4">
          {isCorrect ? 'შემდეგი მაგალითი' : 'თავიდან სცადე'}
        </Button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { MathProblem, Operation, GameState } from './types';
import { Button } from './components/Button';
import { ResultOverlay } from './components/ResultOverlay';

// Helper to generate a valid problem based on kid-friendly rules
const generateProblem = (): MathProblem => {
  const operations = [Operation.Add, Operation.Subtract, Operation.Multiply, Operation.Divide];
  const op = operations[Math.floor(Math.random() * operations.length)];

  let num1 = 0;
  let num2 = 0;
  let answer = 0;

  switch (op) {
    case Operation.Add:
      num1 = Math.floor(Math.random() * 20) + 1; // 1-20
      num2 = Math.floor(Math.random() * 20) + 1;
      answer = num1 + num2;
      break;
    case Operation.Subtract:
      num1 = Math.floor(Math.random() * 20) + 5; // Ensure first number is big enough
      num2 = Math.floor(Math.random() * num1); // Ensure result is positive
      answer = num1 - num2;
      break;
    case Operation.Multiply:
      num1 = Math.floor(Math.random() * 10) + 1; // Keep multiplication simple (1-10)
      num2 = Math.floor(Math.random() * 10) + 1;
      answer = num1 * num2;
      break;
    case Operation.Divide:
      answer = Math.floor(Math.random() * 10) + 1; // Decide the answer first
      num2 = Math.floor(Math.random() * 9) + 2; // Divide by 2-10
      num1 = answer * num2; // Calculate the dividend
      break;
  }

  return { num1, num2, operation: op, answer };
};

const App: React.FC = () => {
  const [problem, setProblem] = useState<MathProblem | null>(null);
  const [userAnswer, setUserAnswer] = useState<string>('');
  const [gameState, setGameState] = useState<GameState>(GameState.Playing);
  const inputRef = useRef<HTMLInputElement>(null);

  // Initialize first problem
  useEffect(() => {
    setProblem(generateProblem());
  }, []);

  // Focus input when game state is playing
  useEffect(() => {
    if (gameState === GameState.Playing) {
      inputRef.current?.focus();
    }
  }, [gameState]);

  const handleSubmit = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!problem || !userAnswer) return;

    const val = parseInt(userAnswer, 10);

    if (isNaN(val)) return;

    if (val === problem.answer) {
      setGameState(GameState.Correct);
    } else {
      setGameState(GameState.Incorrect);
    }
  };

  const handleNext = () => {
    setProblem(generateProblem());
    setUserAnswer('');
    setGameState(GameState.Playing);
  };

  if (!problem) return <div className="min-h-screen flex items-center justify-center">იტვირთება...</div>;

  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-100 to-purple-200 flex flex-col items-center justify-center p-4">

      {/* Header */}
      <header className="absolute top-0 w-full p-6 text-center">
        <h1 className="text-3xl md:text-5xl font-black text-indigo-900 tracking-tight">
          მეფე თომას მათემატიკა 👑
        </h1>
      </header>

      {/* Main Game Card */}
      <main className="bg-white w-full max-w-lg rounded-3xl shadow-2xl p-8 md:p-12 relative overflow-hidden border-b-8 border-indigo-200">

        {/* Decorative background elements */}
        <div className="absolute top-0 left-0 w-full h-4 bg-gradient-to-r from-blue-400 via-purple-400 to-pink-400" />

        <div className="text-center space-y-8">

          <div className="space-y-2">
            <p className="text-gray-500 font-medium uppercase tracking-wider text-sm">გამოთვალე:</p>
            <div className="flex items-center justify-center space-x-4 text-6xl md:text-8xl font-black text-gray-800">
              <span className="text-blue-600">{problem.num1}</span>
              <span className="text-purple-500">{problem.operation}</span>
              <span className="text-blue-600">{problem.num2}</span>
            </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="relative">
              <input
                ref={inputRef}
                type="number"
                inputMode="numeric"
                value={userAnswer}
                onChange={(e) => setUserAnswer(e.target.value)}
                placeholder="?"
                className="w-full text-center text-5xl font-bold py-4 border-4 border-gray-200 rounded-2xl focus:border-purple-500 focus:ring-4 focus:ring-purple-200 outline-none transition-all placeholder-gray-300 text-gray-800"
              />
            </div>

            <Button 
              type="submit" 
              className="w-full text-2xl py-4"
              disabled={!userAnswer}
            >
              შემოწმება
            </Button>
          </form>

        </div>
      </main>

      {/* Footer Instructions */}
      <footer className="mt-8 text-center text-gray-600 max-w-md">
        <p>უპასუხე სწორად და გახდი მათემატიკის მეფე!</p>
      </footer>

      {/* Overlay for Feedback */}
      <ResultOverlay 
        gameState={gameState} 
        correctAnswer={problem.answer}
        onReset={handleNext}
      />
    </div>
  );
};

export default App;

