// --------------------------------------------------------------------------
//  ⚙️ კონფიგურაცია: ჩასვი შენი Google Drive-ის (ან სხვა) ლინკები აქ.
//  მნიშვნელოვანია: Google Drive-ის ფაილზე წვდომა უნდა იყოს "Anyone with the link".
// --------------------------------------------------------------------------
const WIN_IMAGE_URL = "./king.png";   // მაგ: "https://drive.google.com/file/d/....."
const LOSE_IMAGE_URL = "./king1.png"; // მაგ: "https://drive.google.com/file/d/....."

// ეს ფუნქცია ავტომატურად ასწორებს Google Drive-ის ლინკებს
const getDirectLink = (url: string) => {
  if (!url) return '';

  // ამოწმებს არის თუ არა Google Drive-ის ლინკი
  const driveRegex = /drive\.google\.com\/(?:file\/d\/|open\?id=|uc\?id=)([-_\w]+)/;
  const match = url.match(driveRegex);

  if (match && match[1]) {
    // აბრუნებს პირდაპირ გამოსახულების ლინკს
    return `https://drive.google.com/uc?export=view&id=${match[1]}`;
  }

  return url;
};

