// Helper to generate a valid problem based on kid-friendly rules
const generateProblem = (): MathProblem => {
  const operations = [Operation.Add, Operation.Subtract, Operation.Multiply, Operation.Divide];
  const op = operations[Math.floor(Math.random() * operations.length)];

  let num1 = 0;
  let num2 = 0;
  let answer = 0;

  switch (op) {
    case Operation.Add:
      num1 = Math.floor(Math.random() * 20) + 1; // 1-20
      num2 = Math.floor(Math.random() * 20) + 1;
      answer = num1 + num2;
      break;
    case Operation.Subtract:
      num1 = Math.floor(Math.random() * 20) + 5; // Ensure first number is big enough
      num2 = Math.floor(Math.random() * num1); // Ensure result is positive
      answer = num1 - num2;
      break;
    case Operation.Multiply:
      num1 = Math.floor(Math.random() * 10) + 1; // Keep multiplication simple (1-10)
      num2 = Math.floor(Math.random() * 10) + 1;
      answer = num1 * num2;
      break;
    case Operation.Divide:
      answer = Math.floor(Math.random() * 10) + 1; // Decide the answer first
      num2 = Math.floor(Math.random() * 9) + 2; // Divide by 2-10
      num1 = answer * num2; // Calculate the dividend
      break;
  }

  return { num1, num2, operation: op, answer };
};

