            {isSpecialWin ? (
              // თუ ვიდეოზე შეცდომა არ არის, ვცდილობთ პირდაპირ ჩართვას
              !videoError ? (
                <video 
                  ref={videoRef}
                  src={videoDirectSrc} 
                  className="w-full h-full object-cover" 
                  autoPlay 
                  muted 
                  playsInline
                  loop
                  controls={false} // ღილაკების გარეშე
                  onError={() => {
                    // შეცდომის შემთხვევაში გადავდივართ iframe-ზე
                    console.warn("Direct video failed, switching to fallback.");
                    setVideoError(true);
                  }}
                />
              ) : (
                // სათადარიგო ვარიანტი: Iframe (თუ პირდაპირი ლინკი არ მუშაობს)
                <iframe 
                  src={videoEmbedSrc}
                  className="w-full h-full"
                  allow="autoplay; encrypted-media"
                  allowFullScreen
                  title="Special Reward Video"
                />
              )
            ) : (
              !imageError ? (
                <img 
                  src={imageSrc} 
                  alt={isCorrect ? "მეფე თომა" : "სცადე თავიდან"} 
                  className="w-full h-full object-cover"
                  onError={() => setImageError(true)}
                />
              ) : (
                <div className="text-9xl select-none">
                  {isCorrect ? '👑' : '🤔'}
                </div>
              )
            )}
          </div>
        )}

        {!isCorrect && (
          <div className="text-3xl font-bold text-gray-800 mb-8">
            სწორი პასუხი იყო: {correctAnswer}
          </div>
        )}

        <Button onClick={onReset} className="w-full text-2xl py-5 shadow-lg">
          {isCorrect ? 'შემდეგი მაგალითი' : 'თავიდან სცადე'}
