import React, { useEffect, useState } from 'react';
import { GameState } from '../types';
import { Button } from './Button';

// --------------------------------------------------------------------------
//  ⚙️ სურათების კონფიგურაცია
// --------------------------------------------------------------------------

// გამარჯვებულის სურათები (ჩაამატე აქ შენი ლინკები)
const WINNER_IMAGES = [
  "https://drive.google.com/file/d/1FJ6kl0x9SEikqoig6T80SzhYgGL7qdZd/view?usp=drive_link", // GIF
  "https://drive.google.com/file/d/1wuXKSsGy0YgLtw_oElyzRUYWs60h66ct/view?usp=drive_link", // Pic 1
];

// დამარცხებულის სურათები (ჩაამატე აქ შენი ლინკები)
const LOSER_IMAGES = [
  "https://drive.google.com/file/d/1Smhq73OlyJezuTMgFDB3EiSNkup_6H0-/view?usp=drive_link",
];

// სათადარიგო GIF, თუ რამე გაფუჭდა
const FALLBACK_GIF = "https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExN2lsaG1oMnB6eXJ6eXJ6eXJ6eXJ6eXJ6eXJ6eXJ6eXJ6eSZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/l0MYt5jPR6QX5pnqM/giphy.gif";

const getDriveId = (url: string) => {
  if (!url) return null;
  const driveRegex = /drive\.google\.com\/(?:file\/d\/|open\?id=|uc\?id=)([-_\w]+)/;
  const match = url.match(driveRegex);
  return match && match[1] ? match[1] : null;
};

const getDirectLink = (url: string) => {
  if (!url || !url.includes('drive.google.com')) return url;
  const id = getDriveId(url);
  if (!id) return url;
  // Google Drive-ის ლინკების პირდაპირ გახსნა
  return `https://lh3.googleusercontent.com/d/${id}`;
};

interface ResultOverlayProps {
  gameState: GameState;
  onReset: () => void;
  correctAnswer: number;
  message: string;        
  showImage: boolean;     
  isPerfectBlock: boolean; // ახალი პარამეტრი: იყო თუ არა 5-ვე პასუხი სწორი
}

export const ResultOverlay: React.FC<ResultOverlayProps> = ({ 
  gameState, 
  onReset, 
  correctAnswer, 
  message,
  showImage,
  isPerfectBlock
}) => {
  const [showContent, setShowContent] = useState(false);
  const [activeImgSrc, setActiveImgSrc] = useState<string>("");
  const [imageError, setImageError] = useState(false);

  const isCorrect = gameState === GameState.Correct;

  // სურათის ლოგიკა: 5 კითხვის თავზე ვირჩევთ სურათს
  useEffect(() => {
    if (!showImage) return;

    // ვირჩევთ სიას შედეგის მიხედვით
    const sourceArray = isPerfectBlock ? WINNER_IMAGES : LOSER_IMAGES;

    // ვიღებთ შემთხვევით სურათს სიიდან
    const randomIndex = Math.floor(Math.random() * sourceArray.length);
    const rawUrl = sourceArray[randomIndex];

    const finalSrc = getDirectLink(rawUrl);
    setActiveImgSrc(finalSrc);
    setImageError(false);
  }, [showImage, isPerfectBlock]);

  const titleColor = isCorrect ? 'text-green-600' : 'text-red-600';
  const bgColor = isCorrect ? 'bg-green-500/90' : 'bg-red-500/90';

  useEffect(() => {
    if (gameState === GameState.Playing) {
      setShowContent(false);
      return;
    }
    const timer = setTimeout(() => {
      setShowContent(true);
    }, 300);
    return () => clearTimeout(timer);
  }, [gameState]);

  if (gameState === GameState.Playing) return null;

  return (
    <div className={`fixed inset-0 z-50 flex items-center justify-center p-4 backdrop-blur-sm ${bgColor} transition-colors duration-500`}>
      <div className="bg-white rounded-3xl p-6 md:p-8 max-w-2xl w-full shadow-2xl text-center transform animate-bounce-short flex flex-col items-center">

        {/* მთავარი მესიჯი */}
        <h2 className={`text-2xl md:text-4xl font-black mb-8 ${titleColor} leading-tight`}>
          {message}
        </h2>

        {/* სურათი ჩნდება მხოლოდ მე-5 კითხვაზე (როცა showImage true-ა) */}
        {showContent && showImage && (
          <div className={`relative w-full aspect-video mb-8 rounded-2xl overflow-hidden border-4 ${isPerfectBlock ? 'border-yellow-400' : 'border-gray-500'} shadow-xl bg-gray-100 flex items-center justify-center animate-fade-in-up`}>
            {!imageError ? (
              <img 
                key={activeImgSrc}
                src={activeImgSrc} 
                alt="შედეგი" 
                className="w-full h-full object-cover"
                referrerPolicy="no-referrer"
                onError={() => {
                  console.warn("სურათი ვერ ჩაიტვირთა, ირთვება fallback");
                  if (activeImgSrc !== FALLBACK_GIF) {
                     setActiveImgSrc(FALLBACK_GIF);
                  } else {
                     setImageError(true);
                  }
                }}
              />
            ) : (
              <div className="text-9xl select-none">
                {isPerfectBlock ? '👑' : '🥀'}
              </div>
            )}
          </div>
        )}

        <Button onClick={onReset} className="w-full text-2xl py-5 shadow-lg">
          {isCorrect ? 'შემდეგი' : 'თავიდან სცადე'}
        </Button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
