import React, { useState, useEffect, useRef } from 'react';
import { MathProblem, Operation, GameState } from './types';
import { Button } from './components/Button';
import { ResultOverlay } from './components/ResultOverlay';

// ფრაზების სიები
const CORRECT_PHRASES = [
  "ყოჩაღ, თომა კაი ბიჭი ხარ",
  "სააღოლ ძმაო",
  "მალადეეც",
  "ბრავო",
  "შენ აღარ ხუმრობ",
  "მათემატიკოსი კაცი ხარ"
];

const INCORRECT_PHRASES = [
  "არა ბიჭო რა []",
  "[] არა იის",
  "[] რანაირად არის, წესიერად დაითვალე",
  "არასწორია, ასეთი ჭკვიანი კაცი მაგას როგორ ვერ ხვდები"
];

const generateProblem = (): MathProblem => {
  const operations = [Operation.Add, Operation.Subtract, Operation.Multiply, Operation.Divide];
  const op = operations[Math.floor(Math.random() * operations.length)];

  let num1 = 0;
  let num2 = 0;
  let answer = 0;

  switch (op) {
    case Operation.Add:
      num1 = Math.floor(Math.random() * 20) + 1;
      num2 = Math.floor(Math.random() * 20) + 1;
      answer = num1 + num2;
      break;
    case Operation.Subtract:
      num1 = Math.floor(Math.random() * 20) + 5;
      num2 = Math.floor(Math.random() * num1);
      answer = num1 - num2;
      break;
    case Operation.Multiply:
      num1 = Math.floor(Math.random() * 10) + 1;
      num2 = Math.floor(Math.random() * 10) + 1;
      answer = num1 * num2;
      break;
    case Operation.Divide:
      answer = Math.floor(Math.random() * 10) + 1;
      num2 = Math.floor(Math.random() * 9) + 2;
      num1 = answer * num2;
      break;
  }

  return { num1, num2, operation: op, answer };
};

const App: React.FC = () => {
  const [problem, setProblem] = useState<MathProblem | null>(null);
  const [userAnswer, setUserAnswer] = useState<string>('');
  const [gameState, setGameState] = useState<GameState>(GameState.Playing);

  // 5-კითხვიანი ბლოკის ლოგიკა
  const [questionsInBlock, setQuestionsInBlock] = useState<number>(0); 
  const [isPerfectBlock, setIsPerfectBlock] = useState<boolean>(true); // ინახავს თუ არის "სუფთა" ბლოკი (შეცდომების გარეშე)

  const [currentMessage, setCurrentMessage] = useState<string>("");
  const [showRewardImage, setShowRewardImage] = useState<boolean>(false);

  // ვიმახსოვრებთ ბოლო გამოყენებულ ფრაზას (შაბლონს), რომ არ განმეორდეს
  const [lastPhraseTemplate, setLastPhraseTemplate] = useState<string>("");

  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setProblem(generateProblem());
  }, []);

  useEffect(() => {
    if (gameState === GameState.Playing) {
      inputRef.current?.focus();
    }
  }, [gameState]);

  // ფუნქცია, რომელიც არჩევს ფრაზას ისე, რომ წინა ფრაზას არ დაემთხვეს
  const getUniqueRandomPhrase = (list: string[]) => {
    // ფილტრავს სიას: იღებს ყველას გარდა იმისა, რაც ბოლოს იყო
    let candidates = list.filter(phrase => phrase !== lastPhraseTemplate);

    // დაზღვევა: თუ სია ცარიელია (მაგ. სიაში მხოლოდ 1 ელემენტია), ისევ სრული სია ავიღოთ
    if (candidates.length === 0) candidates = list;

    const selected = candidates[Math.floor(Math.random() * candidates.length)];
    setLastPhraseTemplate(selected); // ვიმახსოვრებთ ახალ ფრაზას
    return selected;
  };

  const handleSubmit = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!problem || !userAnswer) return;

    const val = parseInt(userAnswer, 10);
    if (isNaN(val)) return;

    const isCorrect = val === problem.answer;

    if (isCorrect) {
      // მხოლოდ სწორი პასუხის დროს იზრდება კითხვების რაოდენობა
      const nextQuestionsInBlock = questionsInBlock + 1;
      setQuestionsInBlock(nextQuestionsInBlock);

      let message = getUniqueRandomPhrase(CORRECT_PHRASES);

      // მე-5 კითხვის შემოწმება (ბლოკის დასასრული)
      if (nextQuestionsInBlock === 5) {
        setShowRewardImage(true);

        // თუ ბლოკი არ იყო სუფთა (იყო შეცდომები), მესიჯი უნდა შეიცვალოს
        if (!isPerfectBlock) {
           message = "შეცდომები გქონდა! მეფე უკმაყოფილოა.";
        }
      } else {
        setShowRewardImage(false);
      }

      setCurrentMessage(message);
      setGameState(GameState.Correct);
    } else {
      // არასწორი პასუხი: ბლოკი აღარ ითვლება "სუფთად"
      setIsPerfectBlock(false);

      const template = getUniqueRandomPhrase(INCORRECT_PHRASES);
      const finalMessage = template.replace("[]", userAnswer);

      setCurrentMessage(finalMessage);
      setGameState(GameState.Incorrect);
      setShowRewardImage(false);
    }
  };

  const handleNext = () => {
    // თუ პასუხი არასწორი იყო -> ვტოვებთ იგივე კითხვას (Retry)
    if (gameState === GameState.Incorrect) {
      setUserAnswer(''); // ვასუფთავებთ პასუხს
      setGameState(GameState.Playing); // ვაბრუნებთ თამაშს
      return;
    }

    // თუ პასუხი სწორი იყო -> გადავდივართ შემდეგზე
    if (gameState === GameState.Correct) {
      // თუ 5 კითხვა გავიდა, გავანულოთ მთვლელები და სუფთა ბლოკის სტატუსი
      if (questionsInBlock >= 5) {
        setQuestionsInBlock(0);
        setIsPerfectBlock(true); // ახალი ბლოკი იწყება სუფთა ფურცლიდან
      }

      setProblem(generateProblem());
      setUserAnswer('');
      setGameState(GameState.Playing);
      setShowRewardImage(false);
    }
  };

  if (!problem) return <div className="min-h-screen flex items-center justify-center">იტვირთება...</div>;

  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-100 to-purple-200 flex flex-col items-center justify-center p-4">

      <header className="absolute top-0 w-full p-6 text-center flex justify-between px-10 items-center">
        <h1 className="text-2xl md:text-4xl font-black text-indigo-900 tracking-tight">
          თომთემატიკა 👑
        </h1>
        {/* პროგრესი: ვაჩვენოთ მერამდენე კითხვაა 5-დან */}
        <div className="text-indigo-800 font-bold bg-white/50 px-4 py-2 rounded-xl">
           {questionsInBlock}/5
        </div>
      </header>

      <main className="bg-white w-full max-w-lg rounded-3xl shadow-2xl p-8 md:p-12 relative overflow-hidden border-b-8 border-indigo-200">
        <div className="absolute top-0 left-0 w-full h-4 bg-gradient-to-r from-blue-400 via-purple-400 to-pink-400" />

        <div className="text-center space-y-8">
          <div className="space-y-2">
            <p className="text-gray-500 font-medium uppercase tracking-wider text-sm">გამოთვალე:</p>
            <div className="flex items-center justify-center space-x-4 text-6xl md:text-8xl font-black text-gray-800">
              <span className="text-blue-600">{problem.num1}</span>
              <span className="text-purple-500">{problem.operation}</span>
              <span className="text-blue-600">{problem.num2}</span>
            </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="relative">
              <input
                ref={inputRef}
                type="number"
                inputMode="numeric"
                value={userAnswer}
                onChange={(e) => setUserAnswer(e.target.value)}
                placeholder="?"
                className="w-full text-center text-5xl font-bold py-4 border-4 border-gray-200 rounded-2xl focus:border-purple-500 focus:ring-4 focus:ring-purple-200 outline-none transition-all placeholder-gray-300 text-gray-800"
              />
            </div>

            <Button 
              type="submit" 
              className="w-full text-2xl py-4"
              disabled={!userAnswer}
            >
              შემოწმება
            </Button>
          </form>

        </div>
      </main>

      <ResultOverlay 
        gameState={gameState} 
        correctAnswer={problem.answer}
        onReset={handleNext}
        message={currentMessage}
        showImage={showRewardImage}
        isPerfectBlock={isPerfectBlock} // გადავცემთ ახალ პარამეტრს
      />
    </div>
  );
};

export default App;

import React, { useEffect, useState, useRef } from 'react';
import { GameState } from '../types';
