// სათადარიგო GIF, თუ რამე გაფუჭდა
const FALLBACK_GIF = "https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExN2lsaG1oMnB6eXJ6eXJ6eXJ6eXJ6eXJ6eXJ6eXJ6eXJ6eSZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/l0MYt5jPR6QX5pnqM/giphy.gif";

const getDriveId = (url: string) => {
  if (!url) return null;
  const driveRegex = /drive\.google\.com\/(?:file\/d\/|open\?id=|uc\?id=)([-_\w]+)/;
  const match = url.match(driveRegex);
  return match && match[1] ? match[1] : null;
};

const getDirectLink = (url: string) => {
  if (!url || !url.includes('drive.google.com')) return url;
  const id = getDriveId(url);
  if (!id) return url;
  // Google Drive-ის ლინკების პირდაპირ გახსნა
  return `https://lh3.googleusercontent.com/d/${id}`;
};

interface ResultOverlayProps {
  gameState: GameState;
  onReset: () => void;
  correctAnswer: number;
  message: string;        
  showImage: boolean;     
  isPerfectBlock: boolean; // იყო თუ არა 5-ვე პასუხი სწორი
}

export const ResultOverlay: React.FC<ResultOverlayProps> = ({ 
  gameState, 
  onReset, 
  correctAnswer, 
  message,
  showImage,
  isPerfectBlock
}) => {
  const [showContent, setShowContent] = useState(false);

  // ვინახავთ აქტიურ სურათს და მის შესაბამის ტექსტს
  const [activeImgData, setActiveImgData] = useState<{src: string, caption: string} | null>(null);
  const [imageError, setImageError] = useState(false);

  // ცალ-ცალკე ვიმახსოვრებთ გამარჯვებულის და დამარცხებულის ბოლო სურათებს, 
  // რომ შესაბამის კატეგორიაში არ განმეორდეს
  const lastWinnerImageRef = useRef<string | null>(null);
  const lastLoserImageRef = useRef<string | null>(null);

  const isCorrect = gameState === GameState.Correct;

  // Enter-ზე დაჭერის ლოგიკა
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Enter') {
        onReset();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onReset]);

  // სურათის ლოგიკა: 5 კითხვის თავზე ვირჩევთ სურათს და მის ტექსტს
  useEffect(() => {
    if (!showImage) return;

    // განვსაზღვრავთ რომელი სია და რომელი Ref გამოვიყენოთ
    const sourceArray = isPerfectBlock ? WINNER_IMAGES : LOSER_IMAGES;
    const trackingRef = isPerfectBlock ? lastWinnerImageRef : lastLoserImageRef;

    // ვფილტრავთ სიას: ვიღებთ ყველას გარდა იმისა, რომელიც ბოლოს იყო ამ კონკრეტულ კატეგორიაში
    let candidates = sourceArray.filter(item => item.url !== trackingRef.current);

    // დაზღვევა: თუ სია დაცარიელდა (მაგ. სულ 1 სურათია), ისევ სრული სია ავიღოთ
    if (candidates.length === 0) {
      candidates = sourceArray;
    }

    // ვიღებთ შემთხვევით ობიექტს გაფილტრული სიიდან
    const randomIndex = Math.floor(Math.random() * candidates.length);
    const selectedItem = candidates[randomIndex];

    // ვიმახსოვრებთ არჩეულ სურათს შესაბამის Ref-ში
    trackingRef.current = selectedItem.url;

    const finalSrc = getDirectLink(selectedItem.url);

    setActiveImgData({
      src: finalSrc,
      caption: selectedItem.caption
    });
    setImageError(false);
  }, [showImage, isPerfectBlock]);

  const titleColor = isCorrect ? 'text-green-600' : 'text-red-600';
  const bgColor = isCorrect ? 'bg-green-500/90' : 'bg-red-500/90';

  useEffect(() => {
    if (gameState === GameState.Playing) {
      setShowContent(false);
      return;
    }
    const timer = setTimeout(() => {
      setShowContent(true);
    }, 300);
    return () => clearTimeout(timer);
  }, [gameState]);

  if (gameState === GameState.Playing) return null;

  // ტექსტის არჩევა: თუ სურათი ჩანს, ვიღებთ სურათის ტექსტს, თუ არა - ზოგად მესიჯს
  const displayMessage = (showImage && activeImgData) ? activeImgData.caption : message;

  return (
    <div className={`fixed inset-0 z-50 flex items-center justify-center p-4 backdrop-blur-sm ${bgColor} transition-colors duration-500`}>
      <div className="bg-white rounded-3xl p-6 md:p-8 max-w-5xl w-full shadow-2xl text-center transform animate-bounce-short flex flex-col items-center">

        {/* მთავარი მესიჯი */}
        <h2 className={`text-2xl md:text-4xl font-black mb-8 ${titleColor} leading-tight`}>
          {displayMessage}
        </h2>

        {/* სურათი ჩნდება მხოლოდ მე-5 კითხვაზე (როცა showImage true-ა) */}
        {showContent && showImage && activeImgData && (
          <div className={`relative w-full h-[50vh] md:h-[60vh] mb-8 rounded-2xl overflow-hidden border-4 ${isPerfectBlock ? 'border-yellow-400' : 'border-gray-500'} shadow-xl bg-gray-100 flex items-center justify-center animate-fade-in-up`}>
            {!imageError ? (
              <img 
                key={activeImgData.src}
                src={activeImgData.src} 
                alt="შედეგი" 
                className="w-full h-full object-contain"
                referrerPolicy="no-referrer"
                onError={() => {
                  console.warn("სურათი ვერ ჩაიტვირთა, ირთვება fallback");
                  if (activeImgData.src !== FALLBACK_GIF) {
                     setActiveImgData({ ...activeImgData, src: FALLBACK_GIF });
                  } else {
                     setImageError(true);
                  }
                }}
              />
            ) : (
              <div className="text-9xl select-none">
                {isPerfectBlock ? '👑' : '🥀'}
              </div>
            )}
          </div>
        )}

        <Button onClick={onReset} className="w-full text-2xl py-5 shadow-lg">
          {isCorrect ? 'შემდეგი' : 'თავიდან სცადე'}
        </Button>
      </div>
    </div>
  );
};

export enum Operation {
  Add = '+',
  Subtract = '-',
  Multiply = '×',
  Divide = '÷'
}

export interface MathProblem {
  num1: number;
  num2: number;
  num3?: number;       // მესამე რიცხვი (არასავალდებულო)
  operation: Operation;
  operation2?: Operation; // მეორე მოქმედება (არასავალდებულო)
  answer: number;
}

export enum GameState {
  Playing,
  Correct,
  Incorrect
}

import React, { useState, useEffect, useRef } from 'react';
import { MathProblem, Operation, GameState } from './types';
import { Button } from './components/Button';
import { ResultOverlay } from './components/ResultOverlay';

// ფრაზების სიები
const CORRECT_PHRASES = [
  "ყოჩაღ, თომა კაი ბიჭი ხარ",
  "სააღოლ ძმაო",
  "მალადეეც",
  "ბრავო",
  "შენ აღარ ხუმრობ",
  "მათემატიკოსი კაცი ხარ"
];

const INCORRECT_PHRASES = [
  "არა ბიჭო რა []",
  "[] არა იის",
  "[] რანაირად არის, წესიერად დაითვალე",
  "არასწორია, ასეთი ჭკვიანი კაცი მაგას როგორ ვერ ხვდები"
];

const generateProblem = (): MathProblem => {
  const operations = [Operation.Add, Operation.Subtract, Operation.Multiply, Operation.Divide];
  const op = operations[Math.floor(Math.random() * operations.length)];

  let num1 = 0;
  let num2 = 0;
  let answer = 0;

  // მიმატება და გამოკლება - 3 რიცხვიანი ლოგიკა
  if (op === Operation.Add || op === Operation.Subtract) {
    // ვცდილობთ დავაგენერიროთ ისეთი კომბინაცია, რომ პასუხი არ იყოს უარყოფითი
    while (true) {
      // ვირჩევთ ორ მოქმედებას (+ ან -)
      const possibleOps = [Operation.Add, Operation.Subtract];
      const op1 = possibleOps[Math.floor(Math.random() * possibleOps.length)];
      const op2 = possibleOps[Math.floor(Math.random() * possibleOps.length)];

      const n1 = Math.floor(Math.random() * 30) + 10; // 10-დან 40-მდე
      const n2 = Math.floor(Math.random() * 20) + 1;  // 1-დან 20-მდე
      const n3 = Math.floor(Math.random() * 20) + 1;  // 1-დან 20-მდე

      let tempAns = 0;

      // პირველი მოქმედება
      if (op1 === Operation.Add) tempAns = n1 + n2;
      else tempAns = n1 - n2;

      // მეორე მოქმედება
      if (op2 === Operation.Add) tempAns = tempAns + n3;
      else tempAns = tempAns - n3;

      // თუ პასუხი დადებითია (0-ის ჩათვლით), ვაბრუნებთ შედეგს
      if (tempAns >= 0) {
        return { 
          num1: n1, 
          num2: n2, 
          num3: n3, 
          operation: op1, 
          operation2: op2, 
          answer: tempAns 
        };
      }
      // თუ უარყოფითია, ციკლი თავიდან ტრიალებს
    }
  }

  // გამრავლება და გაყოფა - 2 რიცხვიანი ლოგიკა (როგორც იყო)
  switch (op) {
    case Operation.Multiply:
      num1 = Math.floor(Math.random() * 10) + 1;
      num2 = Math.floor(Math.random() * 10) + 1;
      answer = num1 * num2;
      break;
    case Operation.Divide:
      answer = Math.floor(Math.random() * 10) + 1;
      num2 = Math.floor(Math.random() * 9) + 2;
      num1 = answer * num2;
      break;
    default:
       // ეს არ მოხდება, რადგან Add/Sub ზევით არის გაწერილი, მაგრამ TS-სთვის ვტოვებთ
       break;
  }

  return { num1, num2, operation: op, answer };
};

const App: React.FC = () => {
  const [problem, setProblem] = useState<MathProblem | null>(null);
  const [userAnswer, setUserAnswer] = useState<string>('');
  const [gameState, setGameState] = useState<GameState>(GameState.Playing);

  // 5-კითხვიანი ბლოკის ლოგიკა
  const [questionsInBlock, setQuestionsInBlock] = useState<number>(0); 
  const [isPerfectBlock, setIsPerfectBlock] = useState<boolean>(true); // ინახავს თუ არის "სუფთა" ბლოკი (შეცდომების გარეშე)

  const [currentMessage, setCurrentMessage] = useState<string>("");
  const [showRewardImage, setShowRewardImage] = useState<boolean>(false);

  // ვიმახსოვრებთ ბოლო გამოყენებულ ფრაზას (შაბლონს), რომ არ განმეორდეს
  const [lastPhraseTemplate, setLastPhraseTemplate] = useState<string>("");

  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setProblem(generateProblem());
  }, []);

  useEffect(() => {
    if (gameState === GameState.Playing) {
      inputRef.current?.focus();
    }
  }, [gameState]);

  // ფუნქცია, რომელიც არჩევს ფრაზას ისე, რომ წინა ფრაზას არ დაემთხვეს
  const getUniqueRandomPhrase = (list: string[]) => {
    // ფილტრავს სიას: იღებს ყველას გარდა იმისა, რაც ბოლოს იყო
    let candidates = list.filter(phrase => phrase !== lastPhraseTemplate);

    // დაზღვევა: თუ სია ცარიელია (მაგ. სიაში მხოლოდ 1 ელემენტია), ისევ სრული სია ავიღოთ
    if (candidates.length === 0) candidates = list;

    const selected = candidates[Math.floor(Math.random() * candidates.length)];
    setLastPhraseTemplate(selected); // ვიმახსოვრებთ ახალ ფრაზას
    return selected;
  };

  const handleSubmit = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!problem || !userAnswer) return;

    const val = parseInt(userAnswer, 10);
    if (isNaN(val)) return;

    const isCorrect = val === problem.answer;

    if (isCorrect) {
      // მხოლოდ სწორი პასუხის დროს იზრდება კითხვების რაოდენობა
      const nextQuestionsInBlock = questionsInBlock + 1;
      setQuestionsInBlock(nextQuestionsInBlock);

      let message = getUniqueRandomPhrase(CORRECT_PHRASES);

      // მე-5 კითხვის შემოწმება (ბლოკის დასასრული)
      if (nextQuestionsInBlock === 5) {
        setShowRewardImage(true);

        // თუ ბლოკი არ იყო სუფთა (იყო შეცდომები), მესიჯი უნდა შეიცვალოს
        if (!isPerfectBlock) {
           message = "შეცდომები გქონდა! მეფე უკმაყოფილოა.";
        }
      } else {
        setShowRewardImage(false);
      }

      setCurrentMessage(message);
      setGameState(GameState.Correct);
    } else {
      // არასწორი პასუხი: ბლოკი აღარ ითვლება "სუფთად"
      setIsPerfectBlock(false);

      const template = getUniqueRandomPhrase(INCORRECT_PHRASES);
      const finalMessage = template.replace("[]", userAnswer);

      setCurrentMessage(finalMessage);
      setGameState(GameState.Incorrect);
      setShowRewardImage(false);
    }
  };

  const handleNext = () => {
    // თუ პასუხი არასწორი იყო -> ვტოვებთ იგივე კითხვას (Retry)
    if (gameState === GameState.Incorrect) {
      setUserAnswer(''); // ვასუფთავებთ პასუხს
      setGameState(GameState.Playing); // ვაბრუნებთ თამაშს
