const getDriveId = (url: string) => {
  if (!url) return null;
  const driveRegex = /drive\.google\.com\/(?:file\/d\/|open\?id=|uc\?id=)([-_\w]+)/;
  const match = url.match(driveRegex);
  return match && match[1] ? match[1] : null;
};

const getDirectLink = (url: string) => {
  if (!url || !url.includes('drive.google.com')) return url;
  const id = getDriveId(url);
  if (!id) return url;
  // Google Drive-ის ლინკების პირდაპირ გახსნა
  return `https://lh3.googleusercontent.com/d/${id}`;
};

interface ResultOverlayProps {
  gameState: GameState;
  onReset: () => void;
  correctAnswer: number;
  message: string;        
  showImage: boolean;     
  isPerfectBlock: boolean; // იყო თუ არა 5-ვე პასუხი სწორი
}

export const ResultOverlay: React.FC<ResultOverlayProps> = ({ 
  gameState, 
  onReset, 
  correctAnswer, 
  message,
  showImage,
  isPerfectBlock
}) => {
  const [showContent, setShowContent] = useState(false);

  // ვინახავთ აქტიურ სურათს და მის შესაბამის ტექსტს
  const [activeImgData, setActiveImgData] = useState<{src: string, caption: string} | null>(null);
  const [imageError, setImageError] = useState(false);

  // ცალ-ცალკე ვიმახსოვრებთ გამარჯვებულის და დამარცხებულის ბოლო სურათებს, 
  // რომ შესაბამის კატეგორიაში არ განმეორდეს
  const lastWinnerImageRef = useRef<string | null>(null);
  const lastLoserImageRef = useRef<string | null>(null);

  const isCorrect = gameState === GameState.Correct;

  // Enter-ზე დაჭერის ლოგიკა
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Enter') {
        onReset();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onReset]);

  // სურათის ლოგიკა: 3 კითხვის თავზე ვირჩევთ სურათს და მის ტექსტს
  useEffect(() => {
    if (!showImage) return;

    // განვსაზღვრავთ რომელი სია და რომელი Ref გამოვიყენოთ
    const sourceArray = isPerfectBlock ? WINNER_IMAGES : LOSER_IMAGES;
    const trackingRef = isPerfectBlock ? lastWinnerImageRef : lastLoserImageRef;

    // ვფილტრავთ სიას: ვიღებთ ყველას გარდა იმისა, რომელიც ბოლოს იყო ამ კონკრეტულ კატეგორიაში
    let candidates = sourceArray.filter(item => item.url !== trackingRef.current);

    // დაზღვევა: თუ სია დაცარიელდა (მაგ. სულ 1 სურათია), ისევ სრული სია ავიღოთ
    if (candidates.length === 0) {
      candidates = sourceArray;
    }

    // ვიღებთ შემთხვევით ობიექტს გაფილტრული სიიდან
    const randomIndex = Math.floor(Math.random() * candidates.length);
    const selectedItem = candidates[randomIndex];

    // ვიმახსოვრებთ არჩეულ სურათს შესაბამის Ref-ში
    trackingRef.current = selectedItem.url;

    const finalSrc = getDirectLink(selectedItem.url);

    setActiveImgData({
      src: finalSrc,
      caption: selectedItem.caption
    });
    setImageError(false);
  }, [showImage, isPerfectBlock]);

  const titleColor = isCorrect ? 'text-green-600' : 'text-red-600';
  const bgColor = isCorrect ? 'bg-green-500/90' : 'bg-red-500/90';

  useEffect(() => {
    if (gameState === GameState.Playing) {
      setShowContent(false);
      return;
    }
    const timer = setTimeout(() => {
      setShowContent(true);
    }, 300);
    return () => clearTimeout(timer);
  }, [gameState]);

  if (gameState === GameState.Playing) return null;

  // ტექსტის არჩევა: თუ სურათი ჩანს, ვიღებთ სურათის ტექსტს, თუ არა - ზოგად მესიჯს
  const displayMessage = (showImage && activeImgData) ? activeImgData.caption : message;

  return (
    <div className={`fixed inset-0 z-50 flex items-center justify-center p-4 backdrop-blur-sm ${bgColor} transition-colors duration-500`}>
      <div className="bg-white rounded-3xl p-6 md:p-8 max-w-5xl w-full shadow-2xl text-center transform animate-bounce-short flex flex-col items-center">

        {/* მთავარი მესიჯი */}
        <h2 className={`text-2xl md:text-4xl font-black mb-8 ${titleColor} leading-tight`}>
          {displayMessage}
        </h2>

        {/* სურათი ჩნდება მხოლოდ მე-3 კითხვაზე (როცა showImage true-ა) */}
        {showContent && showImage && activeImgData && (
          <div className={`relative w-full h-[50vh] md:h-[60vh] mb-8 rounded-2xl overflow-hidden border-4 ${isPerfectBlock ? 'border-yellow-400' : 'border-gray-500'} shadow-xl bg-gray-100 flex items-center justify-center animate-fade-in-up`}>
            {!imageError ? (
              <img 
                key={activeImgData.src}
                src={activeImgData.src} 
                alt="შედეგი" 
                className="w-full h-full object-contain"
                referrerPolicy="no-referrer"
                onError={() => {
                  console.warn("სურათი ვერ ჩაიტვირთა, ირთვება fallback");
                  if (activeImgData.src !== FALLBACK_GIF) {
                     setActiveImgData({ ...activeImgData, src: FALLBACK_GIF });
                  } else {
                     setImageError(true);
                  }
                }}
              />
            ) : (
              <div className="text-9xl select-none">
                {isPerfectBlock ? '👑' : '🥀'}
              </div>
            )}
          </div>
        )}

        <Button onClick={onReset} className="w-full text-2xl py-5 shadow-lg">
          {isCorrect ? 'შემდეგი' : 'თავიდან სცადე'}
        </Button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { MathProblem, Operation, GameState, MissingPart } from './types';
import { Button } from './components/Button';
import { ResultOverlay } from './components/ResultOverlay';

// ფრაზების სიები
const CORRECT_PHRASES = [
  "ყოჩაღ, თომა კაი ბიჭი ხარ",
  "სააღოლ ძმაო",
  "მალადეეც",
  "ბრავო",
  "შენ აღარ ხუმრობ",
  "მათემატიკოსი კაცი ხარ"
];

const INCORRECT_PHRASES = [
  "არა ბიჭო რა []",
  "[] არა იის",
  "[] რანაირად არის, წესიერად დაითვალე",
  "არასწორია, ასეთი ჭკვიანი კაცი მაგას როგორ ვერ ხვდები"
];

const generateProblem = (): MathProblem => {
  const operations = [Operation.Add, Operation.Subtract, Operation.Multiply, Operation.Divide];
  const op = operations[Math.floor(Math.random() * operations.length)];

  let num1 = 0;
  let num2 = 0;

  // მიმატება და გამოკლება - 3 რიცხვიანი ლოგიკა (აქ ყოველთვის შედეგს ვეძებთ)
  if (op === Operation.Add || op === Operation.Subtract) {
    while (true) {
      const possibleOps = [Operation.Add, Operation.Subtract];
      const op1 = possibleOps[Math.floor(Math.random() * possibleOps.length)];
      const op2 = possibleOps[Math.floor(Math.random() * possibleOps.length)];

      const n1 = Math.floor(Math.random() * 30) + 10; 
      const n2 = Math.floor(Math.random() * 20) + 1;  
      const n3 = Math.floor(Math.random() * 20) + 1;  

      let tempAns = 0;
      if (op1 === Operation.Add) tempAns = n1 + n2;
      else tempAns = n1 - n2;

      if (op2 === Operation.Add) tempAns = tempAns + n3;
      else tempAns = tempAns - n3;

      if (tempAns >= 0) {
        return { 
          num1: n1, 
          num2: n2, 
          num3: n3, 
          operation: op1, 
          operation2: op2, 
          answer: tempAns,
          missingPart: 'result',
          equationResult: tempAns
        };
      }
    }
  }

  // გამრავლება და გაყოფა - 2 რიცხვიანი ლოგიკა
  let equationResult = 0;
  let finalAnswer = 0;
  let missing: MissingPart = 'result';
  let n1 = 0;
  let n2 = 0;

  switch (op) {
    case Operation.Multiply:
      n1 = Math.floor(Math.random() * 10) + 1;
      n2 = Math.floor(Math.random() * 10) + 1;
      equationResult = n1 * n2;
      break;
    case Operation.Divide:
      equationResult = Math.floor(Math.random() * 10) + 1; // განაყოფი
      n2 = Math.floor(Math.random() * 9) + 2; // გამყოფი
      n1 = equationResult * n2; // გასაყოფი
      break;
  }

  // შემთხვევით ვირჩევთ: ან შედეგია გამოსაცნობი, ან მეორე წევრი
  // 50% შანსი რომ იყოს "6 * [] = 36" სტილი
  if (Math.random() > 0.5) {
    missing = 'num2';
    finalAnswer = n2;
  } else {
    missing = 'result';
    finalAnswer = equationResult;
  }

  return { 
    num1: n1, 
    num2: n2, 
    operation: op, 
    answer: finalAnswer, 
    missingPart: missing,
    equationResult: equationResult 
  };
};

const App: React.FC = () => {
  const [problem, setProblem] = useState<MathProblem | null>(null);
  const [userAnswer, setUserAnswer] = useState<string>('');
  const [gameState, setGameState] = useState<GameState>(GameState.Playing);

  // 3-კითხვიანი ბლოკის ლოგიკა
  const [questionsInBlock, setQuestionsInBlock] = useState<number>(0); 
  const [isPerfectBlock, setIsPerfectBlock] = useState<boolean>(true);

  // ვითვლით ზედიზედ რამდენჯერ მოხდა Perfect Block (3/3 სწორი პასუხი)
  const [consecutivePerfectBlocks, setConsecutivePerfectBlocks] = useState<number>(0);

  const [currentMessage, setCurrentMessage] = useState<string>("");
  const [showRewardImage, setShowRewardImage] = useState<boolean>(false);
  const [lastPhraseTemplate, setLastPhraseTemplate] = useState<string>("");

  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setProblem(generateProblem());
  }, []);

  useEffect(() => {
    if (gameState === GameState.Playing) {
      inputRef.current?.focus();
    }
  }, [gameState]);

  const getUniqueRandomPhrase = (list: string[]) => {
    let candidates = list.filter(phrase => phrase !== lastPhraseTemplate);
    if (candidates.length === 0) candidates = list;
    const selected = candidates[Math.floor(Math.random() * candidates.length)];
    setLastPhraseTemplate(selected);
    return selected;
  };

  const handleSubmit = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!problem || !userAnswer) return;

    const val = parseInt(userAnswer, 10);
    if (isNaN(val)) return;

    const isCorrect = val === problem.answer;

    if (isCorrect) {
      const nextQuestionsInBlock = questionsInBlock + 1;
      setQuestionsInBlock(nextQuestionsInBlock);

      let message = getUniqueRandomPhrase(CORRECT_PHRASES);

      // მე-3 კითხვის შემოწმება (ბლოკის დასასრული)
      if (nextQuestionsInBlock === 3) {
        setShowRewardImage(true);
        if (isPerfectBlock) {
           // თუ ბლოკი სუფთაა, ვზრდით ზედიზედ მოგებების რაოდენობას
           setConsecutivePerfectBlocks(prev => prev + 1);
        } else {
           message = "შეცდომები გქონდა! მეფე უკმაყოფილოა.";
        }
      } else {
        setShowRewardImage(false);
      }

      setCurrentMessage(message);
      setGameState(GameState.Correct);
    } else {
      // არასწორი პასუხის დროს სუფთა ბლოკიც უქმდება და სერიაც წყდება
      setIsPerfectBlock(false);
      setConsecutivePerfectBlocks(0);

      const template = getUniqueRandomPhrase(INCORRECT_PHRASES);
      const finalMessage = template.replace("[]", userAnswer);

      setCurrentMessage(finalMessage);
      setGameState(GameState.Incorrect);
      setShowRewardImage(false);
    }
  };

  const handleNext = () => {
    if (gameState === GameState.Incorrect) {
      setUserAnswer('');
      setGameState(GameState.Playing);
      return;
    }

    if (gameState === GameState.Correct) {
      // თუ 3 კითხვა გავიდა, გავანულოთ მთვლელები და სუფთა ბლოკის სტატუსი
      if (questionsInBlock >= 3) {
        setQuestionsInBlock(0);
        setIsPerfectBlock(true);
      }

      setProblem(generateProblem());
      setUserAnswer('');
      setGameState(GameState.Playing);
      setShowRewardImage(false);
    }
  };

  if (!problem) return <div className="min-h-screen flex items-center justify-center">იტვირთება...</div>;

  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-100 to-purple-200 flex flex-col items-center justify-center p-4">

      <header className="absolute top-0 w-full p-6 text-center flex justify-between px-10 items-center">
        <h1 className="text-2xl md:text-4xl font-black text-indigo-900 tracking-tight">
          თომთემატიკა 👑
        </h1>
        <div className="text-indigo-800 font-bold bg-white/50 px-4 py-2 rounded-xl">
           {questionsInBlock}/3
        </div>
      </header>

      <main className="bg-white w-full max-w-lg rounded-3xl shadow-2xl p-8 md:p-12 relative overflow-hidden border-b-8 border-indigo-200">
        <div className="absolute top-0 left-0 w-full h-4 bg-gradient-to-r from-blue-400 via-purple-400 to-pink-400" />

        <div className="text-center space-y-8">
          <div className="space-y-2">
            <p className="text-gray-500 font-medium uppercase tracking-wider text-sm">
              {problem.missingPart === 'result' ? 'გამოთვალე:' : 'იპოვე გამოტოვებული რიცხვი:'}
            </p>

            <div className="flex flex-wrap items-center justify-center gap-2 md:gap-4 text-5xl md:text-7xl font-black text-gray-800">
              {/* პირველი რიცხვი */}
              <span className="text-blue-600">
                {problem.missingPart === 'num1' ? <span className="text-orange-400">?</span> : problem.num1}
              </span>

              {/* მოქმედება */}
              <span className="text-purple-500">{problem.operation}</span>

              {/* მეორე რიცხვი */}
              <span className="text-blue-600">
                {problem.missingPart === 'num2' ? <span className="text-orange-400">?</span> : problem.num2}
              </span>

              {/* მესამე რიცხვი და მეორე მოქმედება (თუ არსებობს - მხოლოდ მიმატება/გამოკლებისთვის) */}
              {problem.operation2 && problem.num3 !== undefined && (
                <>
                  <span className="text-purple-500">{problem.operation2}</span>
                  <span className="text-blue-600">{problem.num3}</span>
                </>
              )}

              {/* ტოლობა და შედეგი (მხოლოდ მაშინ, თუ შედეგი არაა გამოსაცნობი) */}
              {problem.missingPart !== 'result' && (
                <>
                  <span className="text-gray-400">=</span>
                  <span className="text-gray-800">{problem.equationResult}</span>
                </>
              )}
            </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="relative">
              <input
                ref={inputRef}
                type="number"
                inputMode="numeric"
                value={userAnswer}
                onChange={(e) => setUserAnswer(e.target.value)}
                placeholder="?"
                className="w-full text-center text-5xl font-bold py-4 border-4 border-gray-200 rounded-2xl focus:border-purple-500 focus:ring-4 focus:ring-purple-200 outline-none transition-all placeholder-gray-300 text-gray-800"
              />
            </div>

            <Button 
              type="submit" 
              className="w-full text-2xl py-4"
              disabled={!userAnswer}
            >
              შემოწმება
            </Button>
          </form>

        </div>
      </main>

      <ResultOverlay 
        gameState={gameState} 
        correctAnswer={problem.answer}
        onReset={handleNext}
        message={currentMessage}
        showImage={showRewardImage}
        isPerfectBlock={isPerfectBlock}
        consecutivePerfectBlocks={consecutivePerfectBlocks}
      />
    </div>
  );
};

